window.LQTACSystemFonts=(()=>{
let cached=null,pending=null;
async function list(refresh=false){if(pending)return pending;if(cached&&!refresh&&Date.now()-cached.scannedAt<120000)return cached;pending=window.lqtacDesktop.systemFonts(refresh);try{cached=await pending;return cached;}finally{pending=null;}}
function bind(select,{current=()=>select.value||'Segoe UI',onReady=()=>{}}={}){
 const box=document.createElement('div');box.className='system-font-picker';const search=document.createElement('input');search.type='search';search.placeholder='Buscar fuente instalada…';search.setAttribute('aria-label','Buscar fuente instalada');const refresh=document.createElement('button');refresh.type='button';refresh.textContent='Actualizar fuentes';const info=document.createElement('p');info.setAttribute('role','status');const sample=document.createElement('p');sample.textContent='Aa Bb 123 · Texto de muestra';sample.style.cssText='font-size:20px;margin:6px 0;overflow-wrap:anywhere';box.append(search,refresh,info,sample);select.after(box);let data=null,alive=true,ready;
 function set(name){if(!LQTACFontModel.valid(name))name='Segoe UI';let option=[...select.options].find(o=>o.value===name);if(!option){option=new Option(name,name);select.add(option);}select.value=name;note(name);}
 function note(name){const missing=data&&!data.families.some(f=>f.toLocaleLowerCase()===name.toLocaleLowerCase());info.textContent=data?data.families.length+' fuentes instaladas'+(missing?' · «'+name+'» no está instalada aquí: se mostrará con una fuente de sustitución. Se conserva su nombre.':''): 'Leyendo fuentes de Windows…';sample.style.fontFamily=LQTACFontModel.css(name)+', "Segoe UI", sans-serif';}
 function paint(){if(!alive||!select.isConnected)return;const name=current()||select.value||'Segoe UI',term=search.value.toLocaleLowerCase(),fonts=(data?.families||['Segoe UI','Arial','Verdana','Georgia','Consolas']).filter(n=>n.toLocaleLowerCase().includes(term));select.replaceChildren();for(const font of fonts){const o=new Option(font,font);select.add(o);}set(name);}
 async function load(force=false){refresh.disabled=true;try{data=await list(force);if(!alive||!select.isConnected)return;paint();onReady(data);}catch(e){if(alive&&select.isConnected)info.textContent='No se pudo leer la lista de fuentes: '+e.message+'. Puedes conservar la fuente actual o reintentar.';}finally{if(alive)refresh.disabled=false;}}
 search.oninput=paint;refresh.onclick=()=>{ready=load(true);};select.addEventListener('input',()=>note(select.value));set(current());ready=load();return {set,refresh:()=>ready=load(true),get ready(){return ready;},dispose(){alive=false;}};
}
const css=document.createElement('style');css.textContent='.system-font-picker{margin:6px 0 12px}.system-font-picker input{width:100%;box-sizing:border-box}.system-font-picker button{margin-top:5px;font-size:11px}.system-font-picker [role=status]{font-size:11px;color:var(--muted);line-height:1.4}';document.head.append(css);
return {list,bind};})();
